"""Audio 2.0 synthesised cinematic + gap-filling sounds (original, generated by our own code; registry source 'synth').
Deterministic: every sound is a pure function of its seed. Used where the downloaded library is thin (risers, sub
booms, drones, whooshes) or missing (footsteps on sand / snow / mud / water) - always described as synthesised."""
import os, sys
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, "..", "audio"))
from dsp import SR, ns, rng, lp, hp, bp, pan, colored  # noqa: E402

def _t(d): return np.arange(ns(d)) / SR
def _env(n, a, d, curve=3.0):
    t = np.linspace(0, 1, n); ai = max(1, int(n * a)); e = np.ones(n); e[:ai] = np.linspace(0, 1, ai) ** 2; e[ai:] = (1 - np.linspace(0, 1, n - ai)) ** curve; return e
def _norm(x, peak=0.7): m = np.abs(x).max(); return x * (peak / m) if m > 0 else x
def _sweep_noise(r, dur, f0, f1, q=2.5):
    n = ns(dur); z = r.standard_normal(n); out = np.zeros(n); seg = ns(0.02)
    for i in range(0, n, seg):
        f = f0 * (f1 / f0) ** (i / n); out[i:i + seg] = bp(z[max(0, i - seg):i + seg], max(40, f / (1 + 1 / q)), min(20000, f * (1 + 1 / q)))[-len(out[i:i + seg]):]
    return out

def riser(seed, dur=3.2):
    r = rng(seed); t = _t(dur); n = len(t); u = t / dur
    nz = _sweep_noise(r, dur, 300, 7000) * u ** 2.2; tone = sum(np.sin(2 * np.pi * np.cumsum(f0 * 2 ** (u * 2.0)) / SR) / (k + 1) for k, f0 in enumerate([110, 165.5, 220.7]))
    x = 0.6 * nz + 0.35 * tone * u ** 2.6; x[-ns(0.03):] *= np.linspace(1, 0, ns(0.03)); return _norm(np.stack([x, np.roll(x, 37)]))
def whoosh(seed, dur=0.9):
    r = rng(seed); x = _sweep_noise(r, dur, 250, 3500) * _env(ns(dur), 0.45, 0.55, 2.2); p = np.linspace(-0.7, 0.7, len(x))
    return _norm(np.stack([x * np.cos((p + 1) * np.pi / 4), x * np.sin((p + 1) * np.pi / 4)]) * 1.4)
def swish(seed): return whoosh(seed, 0.35)
def sub_boom(seed, dur=2.6):
    r = rng(seed); t = _t(dur); f = 38 + 32 * np.exp(-t * 6); x = np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t * 1.6)
    click = lp(r.standard_normal(len(t)) * np.exp(-t * 60), 1800); return _norm(np.stack([x + 0.25 * click] * 2), 0.8)
def cine_impact(seed, dur=3.0):
    r = rng(seed); t = _t(dur); body = np.sin(2 * np.pi * np.cumsum(55 + 60 * np.exp(-t * 9)) / SR) * np.exp(-t * 2.2)
    mid = bp(r.standard_normal(len(t)), 120, 900) * np.exp(-t * 7); tail = lp(r.standard_normal(len(t)), 2500) * np.exp(-t * 1.4) * 0.12
    x = body + 0.5 * mid + tail; return _norm(np.stack([x, x + 0.05 * np.roll(tail, 400)]), 0.8)
def drone(seed, dur=10.0):
    r = rng(seed); t = _t(dur); base = 55 * 2 ** (r.integers(0, 5) / 12); x = np.zeros(len(t))
    for k, d in enumerate([0, 0.11, -0.07, 7.02, 12.03]): ph = r.uniform(0, 6.28); x += np.sin(2 * np.pi * base * 2 ** (d / 12) * t + ph + 0.4 * np.sin(2 * np.pi * 0.07 * t * (k + 1))) / (1 + k * 0.6)
    x = lp(x, 900) * (0.6 + 0.4 * np.sin(2 * np.pi * 0.11 * t) ** 2); x[:ns(1.5)] *= np.linspace(0, 1, ns(1.5)); x[-ns(1.5):] *= np.linspace(1, 0, ns(1.5)); return _norm(np.stack([x, np.roll(x, 211)]), 0.6)
def reverse_swell(seed, dur=1.6):
    x = cine_impact(seed, dur)[:, ::-1].copy(); x[:, :ns(0.05)] *= np.linspace(0, 1, ns(0.05)); return x
def tension(seed, dur=6.0):
    r = rng(seed); t = _t(dur); x = sum(np.sin(2 * np.pi * f * t + r.uniform(0, 6)) for f in [880, 932.3, 987.8]) * (0.6 + 0.4 * np.sin(2 * np.pi * 6.5 * t))
    x = x * np.minimum(1, t / 2.0) * np.minimum(1, (dur - t) / 1.0); return _norm(np.stack([x, np.roll(x, 97)]), 0.35)
def accent(seed, dur=3.0):
    t = _t(dur); x = sum(np.sin(2 * np.pi * f * t) * np.exp(-t * (1.2 + k)) / (k + 1) for k, f in enumerate([523.25, 1046.5, 1568.0, 2093.0])); return _norm(np.stack([x, x]), 0.5)
def pop(seed): t = _t(0.18); x = np.sin(2 * np.pi * np.cumsum(900 - 600 * t / 0.18) / SR) * np.exp(-t * 35); return _norm(np.stack([x, x]), 0.6)
def rustle(seed, dur=0.5):
    r = rng(seed); x = bp(r.standard_normal(ns(dur)), 1500, 7000) * _env(ns(dur), 0.3, 0.7, 2) * (0.6 + 0.4 * np.abs(np.sin(np.linspace(0, 9, ns(dur))))); return _norm(np.stack([x, x]), 0.4)
def step(seed, kind):
    """synthesised footsteps for surfaces the library lacks: soft crunch (sand / snow), squelch (mud), splash (water)"""
    r = rng(seed); d = 0.35 if kind != "water" else 0.5; t = _t(d); z = r.standard_normal(len(t))
    if kind == "sand": x = bp(z, 900, 6000) * np.exp(-t * 18) * (1 + 0.6 * (r.random(len(t)) > 0.995))
    elif kind == "snow": x = bp(z * (r.random(len(t)) > 0.7), 600, 4000) * np.exp(-t * 11)
    elif kind == "mud": x = lp(z, 700) * np.exp(-t * 14) + 0.3 * np.sin(2 * np.pi * 180 * t) * np.exp(-t * 25)
    else: x = bp(z, 400, 5000) * np.exp(-t * 7) * (1 + np.sin(2 * np.pi * 9 * t))
    x[:ns(0.004)] *= np.linspace(0, 1, ns(0.004)); return _norm(np.stack([x, x]), 0.6)
SYNTH = {"riser": riser, "riserShort": lambda s: riser(s, 1.6), "whoosh": whoosh, "swish": swish, "subBoom": sub_boom, "cineImpact": cine_impact, "drone": drone, "reverseSwell": reverse_swell,
         "tension": tension, "accent": accent, "pop": pop, "rustle": rustle, "stepSand": lambda s: step(s, "sand"), "stepSnow": lambda s: step(s, "snow"), "stepMud": lambda s: step(s, "mud"), "stepWater": lambda s: step(s, "water")}
